import { describe, expect, it } from "vitest";
import { parseSavedVariablesLua } from "@/ingestion/savedvariables-parser";

const SAMPLE_LUA = `
-- Auto-generated by World of Warcraft: Forever
WoWForeverFarmOptimizerDB = {
  ["schemaVersion"] = 1,
  ["addonVersion"] = "0.1.0",
  ["clientBuild"] = "1.60.1.70959",
  ["region"] = "EU",
  ["updatedAt"] = 1795270000,
  ["creatures"] = {
    [3931] = {
      ["id"] = 3931,
      ["name"] = "Shadethicket Oracle",
      ["minLevel"] = 30,
      ["maxLevel"] = 31,
      ["kills"] = 100,
      ["lootedCorpses"] = 100,
      ["rawCoinCopper"] = 8500,
      ["activeSeconds"] = 3600,
      ["items"] = {
        [250385] = {
          ["drops"] = 1,
          ["totalQty"] = 1,
          ["minQty"] = 1,
          ["maxQty"] = 1,
        },
        [4606] = {
          ["drops"] = 7,
          ["totalQty"] = 14,
          ["minQty"] = 1,
          ["maxQty"] = 3,
        },
      },
      ["spawns"] = {
        {
          ["k"] = "1440:67:81",
          ["map"] = 1440,
          ["x"] = 66.8,
          ["y"] = 81.2,
        },
      },
    },
  },
}
`;

describe("parseSavedVariablesLua", () => {
  it("parses creature kills, new Forever 250xxx drops, exact quantities, spawns, and measured KPH", () => {
    const parsed = parseSavedVariablesLua(SAMPLE_LUA);

    expect(parsed.schemaVersion).toBe(1);
    expect(parsed.clientBuild).toBe("1.60.1.70959");
    expect(parsed.region).toBe("EU");
    expect(parsed.creatures).toHaveLength(1);

    const oracle = parsed.creatures[0]!;
    expect(oracle.npcId).toBe(3931);
    expect(oracle.name).toBe("Shadethicket Oracle");
    expect(oracle.kills).toBe(100);
    expect(oracle.rawCoinCopper).toBe(8500);
    expect(oracle.measuredKillsPerHour).toBe(100);
    expect(oracle.spawns).toEqual([{ mapId: 1440, x: 66.8, y: 81.2 }]);

    const recipe = oracle.items.find((i) => i.itemId === 250385);
    expect(recipe).toEqual({
      itemId: 250385,
      drops: 1,
      totalQty: 1,
      minQty: 1,
      maxQty: 1,
    });

    const morel = oracle.items.find((i) => i.itemId === 4606);
    expect(morel).toEqual({
      itemId: 4606,
      drops: 7,
      totalQty: 14,
      minQty: 1,
      maxQty: 3,
    });
  });

  it("rejects empty files or files missing WoWForeverFarmOptimizerDB", () => {
    expect(() => parseSavedVariablesLua("")).toThrow(/empty/i);
    expect(() => parseSavedVariablesLua("OtherAddonDB = { a = 1 }")).toThrow(
      /WoWForeverFarmOptimizerDB/i
    );
  });
});
